#include <bits/stdc++.h>
using namespace std;

static char ibuf[1 << 16];
static int ipos = 0, ilen = 0;
inline int gc() {
    if (ipos == ilen) {
        ilen = (int)fread(ibuf, 1, sizeof(ibuf), stdin);
        ipos = 0;
        if (ilen <= 0) return -1;
    }
    return ibuf[ipos++];
}
inline int readInt() {
    int c = gc();
    while (c != -1 && (c < '0' || c > '9')) c = gc();
    int x = 0;
    while (c >= '0' && c <= '9') { x = x * 10 + (c - '0'); c = gc(); }
    return x;
}

const int LOG = 17;

int up[LOG][100005];
int mn[LOG][100005];
int dep[100005];
int dsu[100005];
vector<pair<int,int>> adj[100005];

int find(int x) {
    while (dsu[x] != x) { dsu[x] = dsu[dsu[x]]; x = dsu[x]; }
    return x;
}

int main() {
    int N = readInt(), B = readInt();
    vector<array<int,3>> edges(B); // {peso, u, v}
    edges.reserve(B);
    for (int i = 0; i < B; i++) {
        int u = readInt(), v = readInt(), w = readInt();
        edges[i] = {w, u, v};
    }
    sort(edges.begin(), edges.end(),
         [](const array<int,3>& a, const array<int,3>& b){ return a[0] > b[0]; });

    for (int i = 1; i <= N; i++) dsu[i] = i;

    // Kruskal para Árvore Geradora Máxima
    int cnt = 0;
    for (auto& e : edges) {
        int u = e[1], v = e[2], w = e[0];
        int a = find(u), b = find(v);
        if (a != b) {
            dsu[a] = b;
            adj[u].push_back({v, w});
            adj[v].push_back({u, w});
            if (++cnt == N - 1) break;
        }
    }

    // BFS a partir do nó 1
    vector<int> q; q.reserve(N);
    vector<char> vis(N + 1, 0);
    q.push_back(1); vis[1] = 1;
    dep[1] = 0; up[0][1] = 0; mn[0][1] = INT_MAX;
    for (size_t i = 0; i < q.size(); i++) {
        int u = q[i];
        for (auto& pr : adj[u]) {
            int v = pr.first, w = pr.second;
            if (!vis[v]) {
                vis[v] = 1;
                dep[v] = dep[u] + 1;
                up[0][v] = u;
                mn[0][v] = w;
                q.push_back(v);
            }
        }
    }

    // Binary lifting: menor capacidade de aresta no caminho de v até o ancestral 2^k
    for (int k = 1; k < LOG; k++) {
        const int* upk1 = up[k - 1];
        const int* mnk1 = mn[k - 1];
        int* upk = up[k];
        int* mnk = mn[k];
        for (int v = 1; v <= N; v++) {
            int p = upk1[v];
            if (p == 0) { upk[v] = 0; mnk[v] = INT_MAX; }
            else { upk[v] = upk1[p]; mnk[v] = min(mnk1[v], mnk1[p]); }
        }
    }

    int C = readInt();
    string out;
    out.reserve((size_t)C * 8 + 16);
    char tmp[16];
    while (C--) {
        int x = readInt(), y = readInt();
        int res = INT_MAX;
        if (dep[x] < dep[y]) swap(x, y);
        int diff = dep[x] - dep[y];
        for (int k = 0; diff; k++, diff >>= 1)
            if (diff & 1) { res = min(res, mn[k][x]); x = up[k][x]; }
        if (x != y) {
            for (int k = LOG - 1; k >= 0; k--)
                if (up[k][x] != up[k][y]) {
                    res = min(res, min(mn[k][x], mn[k][y]));
                    x = up[k][x]; y = up[k][y];
                }
            res = min(res, min(mn[0][x], mn[0][y]));
        }
        int len = snprintf(tmp, sizeof(tmp), "%d\n", res);
        out.append(tmp, len);
    }
    fwrite(out.data(), 1, out.size(), stdout);
    return 0;
}
